params.query:
-- Drop existing foreign key constraint
ALTER TABLE recall_images DROP CONSTRAINT IF EXISTS recall_images_recall_id_fkey;

-- Add foreign key with cascade delete
ALTER TABLE recall_images 
ADD CONSTRAINT recall_images_recall_id_fkey 
FOREIGN KEY (recall_id) 
REFERENCES recalls(id) 
ON DELETE CASCADE;

-- Rename image_url to image_path if it exists
DO $$ 
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'recall_images' AND column_name = 'image_url'
  ) THEN
    ALTER TABLE recall_images RENAME COLUMN image_url TO image_path;
  END IF;
END $$;

-- Create users table to store additional user information
CREATE TABLE IF NOT EXISTS public.users (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable RLS on users table
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for users table
CREATE POLICY "Users can view their own profile"
  ON public.users
  FOR SELECT
  USING (auth.uid() = id);

CREATE POLICY "Users can update their own profile"
  ON public.users
  FOR UPDATE
  USING (auth.uid() = id);

CREATE POLICY "Users can insert their own profile"
  ON public.users
  FOR INSERT
  WITH CHECK (auth.uid() = id);

-- Create login_history table
CREATE TABLE IF NOT EXISTS public.login_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  login_at TIMESTAMPTZ DEFAULT NOW(),
  ip_address TEXT,
  user_agent TEXT
);

-- Enable RLS on login_history table
ALTER TABLE public.login_history ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for login_history table
CREATE POLICY "Users can view their own login history"
  ON public.login_history
  FOR SELECT
  USING (auth.uid() = user_id);

CREATE POLICY "Users can insert their own login history"
  ON public.login_history
  FOR INSERT
  WITH CHECK (auth.uid() = user_id);

-- Add foreign key constraint to search_history if not exists
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.table_constraints 
    WHERE constraint_name = 'search_history_user_id_fkey'
  ) THEN
    ALTER TABLE public.search_history
    ADD CONSTRAINT search_history_user_id_fkey
    FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
  END IF;
END $$;

-- Update RLS policies for recalls to be user-specific
DROP POLICY IF EXISTS "Anyone can view recalls" ON public.recalls;
DROP POLICY IF EXISTS "Anyone can insert recalls" ON public.recalls;
DROP POLICY IF EXISTS "Anyone can update recalls" ON public.recalls;
DROP POLICY IF EXISTS "Anyone can delete recalls" ON public.recalls;

CREATE POLICY "Users can view their own recalls"
  ON public.recalls
  FOR SELECT
  USING (auth.uid() = user_id);

CREATE POLICY "Users can insert their own recalls"
  ON public.recalls
  FOR INSERT
  WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update their own recalls"
  ON public.recalls
  FOR UPDATE
  USING (auth.uid() = user_id);

CREATE POLICY "Users can delete their own recalls"
  ON public.recalls
  FOR DELETE
  USING (auth.uid() = user_id);

-- Update RLS policies for recall_images to be user-specific
DROP POLICY IF EXISTS "Anyone can view recall images" ON public.recall_images;
DROP POLICY IF EXISTS "Anyone can insert recall images" ON public.recall_images;
DROP POLICY IF EXISTS "Anyone can delete recall images" ON public.recall_images;

CREATE POLICY "Users can view their own recall images"
  ON public.recall_images
  FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM public.recalls
      WHERE recalls.id = recall_images.recall_id
      AND recalls.user_id = auth.uid()
    )
  );

CREATE POLICY "Users can insert their own recall images"
  ON public.recall_images
  FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.recalls
      WHERE recalls.id = recall_images.recall_id
      AND recalls.user_id = auth.uid()
    )
  );

CREATE POLICY "Users can delete their own recall images"
  ON public.recall_images
  FOR DELETE
  USING (
    EXISTS (
      SELECT 1 FROM public.recalls
      WHERE recalls.id = recall_images.recall_id
      AND recalls.user_id = auth.uid()
    )
  );

-- Update RLS policies for search_history to be user-specific
DROP POLICY IF EXISTS "Users can view their own search history" ON public.search_history;
DROP POLICY IF EXISTS "Users can insert their own search history" ON public.search_history;
DROP POLICY IF EXISTS "Users can update their own search history" ON public.search_history;
DROP POLICY IF EXISTS "Users can delete their own search history" ON public.search_history;

CREATE POLICY "Users can view their own search history"
  ON public.search_history
  FOR SELECT
  USING (auth.uid() = user_id);

CREATE POLICY "Users can insert their own search history"
  ON public.search_history
  FOR INSERT
  WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update their own search history"
  ON public.search_history
  FOR UPDATE
  USING (auth.uid() = user_id);

CREATE POLICY "Users can delete their own search history"
  ON public.search_history
  FOR DELETE
  USING (auth.uid() = user_id);

-- Add image_data column to store base64 encoded image data
ALTER TABLE public.recall_images
ADD COLUMN IF NOT EXISTS image_data TEXT;

-- Add image_uri column to store original URI
ALTER TABLE public.recall_images
ADD COLUMN IF NOT EXISTS image_uri TEXT;

-- Drop the old image_path column and add image_data column
ALTER TABLE recall_images DROP COLUMN IF EXISTS image_path;

-- Add image_data column to store binary image data
ALTER TABLE recall_images ADD COLUMN image_data bytea NOT NULL DEFAULT ''::bytea;

-- Add content_type column to store the MIME type
ALTER TABLE recall_images ADD COLUMN content_type text NOT NULL DEFAULT 'image/jpeg';
